const rows = $input.all().map(item => item.json);

if (!rows.length) {
  return [
    {
      json: {
        summary: 'GitHub Digest (last 24h)\n\nNo signed GitHub events found.',
      },
    },
  ];
}

const lines = rows.map((row, index) => {
  return `${index + 1}. ${row.repository_full_name} — ${row.event} / ${row.action} — ${row.event_count} event(s) — latest ${row.latest_event}`;
});

return [
  {
    json: {
      summary: `GitHub Digest (last 24h)\n\n${lines.join('\n')}`,
    },
  },
];
